import sys, re
sys.path.insert(0, "verifier")
import source

pages = source.pages_for("ZEMKG5EA")
norm = {p: source.normalize(t) for p, t in pages.items()}

BRACKET = re.compile(r"\[\s*\d+(?:\s*[-–,]\s*\d+)*\s*\]")
HEADER  = re.compile(r"Article in Press Journal of Orthopaedic Surgery and Research https://doi\.org/\S+")
REFHEAD = re.compile(r"\bReferences\b")

def band_and_present(texts):
    present = set()
    for t in texts:
        present |= {int(v) for v in source.numbers_on(t) if v == int(v)}
    b = 0
    while b + 1 in present:
        b += 1
    return b, present

def variant(strip_refs, strip_brackets, strip_header):
    out = {}
    for p, t in norm.items():
        if strip_refs:
            m = REFHEAD.search(t)
            if m:
                t = t[:m.start()]          # cut bibliography onward
            elif p > 9:
                t = ""                      # pages after refs start are all bibliography
        if strip_brackets:
            t = BRACKET.sub(" ", t)
        if strip_header:
            t = HEADER.sub(" ", t)
        out[p] = t
    return out

for label, args in [
    ("baseline                 ", (0,0,0)),
    ("refs only                ", (1,0,0)),
    ("refs + brackets          ", (1,1,0)),
    ("refs + brackets + header ", (1,1,1)),
]:
    v = variant(*args)
    b, present = band_and_present(v.values())
    small = sorted(i for i in present if 0 <= i <= 40)
    chars = sum(len(x) for x in v.values())
    print(f"{label} band={b:<3} chars={chars:>6}  ints 0-40 present: {small}")
